// CmsPro MD文档解析器 - 本地化增强版
// 支持大型技术文档（3000+行、100+代码块、多表格/引用/列表）
(function() {
'use strict';

const BLOCKQUOTE_PLACEHOLDER = '\x00BQ';
const TABLE_PLACEHOLDER = '\x00TBL';
const LIST_PLACEHOLDER = '\x00LIST';

window.marked = {
  parse: function(text) {
    text = text.replace(/\\(.)/g, '$1');

    // —— 第1步：提取并保护代码块 ——
    const codeBlocks = [];
    text = text.replace(/```(\w*)\n?([\s\S]*?)```/g, function(match, lang, code) {
      const idx = codeBlocks.length;
      const l = lang ? lang.toLowerCase() : '';
      codeBlocks.push({
        lang: l,
        html: '<pre class="' + (l ? l + '-code' : '') + '" data-lang="' + l + '"><code class="' + (l ? 'language-' + l : '') + '">' +
          code.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;') +
          '</code></pre>'
      });
      return '\x00CB' + idx + '\x00';
    });

    // —— 第2步：处理引用块（整体扫描，生成嵌套 HTML）——
    text = this._parseBlockquotes(text);

    // —— 第3步：处理标题 ——
    text = text.replace(/^#{6}\s+(.*)$/gim, '<h6>$1</h6>');
    text = text.replace(/^#{5}\s+(.*$)/gim, '<h5>$1</h5>');
    text = text.replace(/^#{4}\s+(.*$)/gim, '<h4>$1</h4>');
    text = text.replace(/^#{3}\s+(.*$)/gim, '<h3>$1</h3>');
    text = text.replace(/^#{2}\s+(.*$)/gim, '<h2>$1</h2>');
    text = text.replace(/^#\s+(.*$)/gim, '<h1>$1</h1>');

    // —— 第4步：水平线 ——
    text = text.replace(/^\s*(?:-{3,}|\*{3,}|_{3,})\s*$/gim, '<hr>');

    // —— 第5步：处理表格（以行组为单位）——
    text = this._parseTables(text);

    // —— 第6步：处理列表 ——
    text = this._parseLists(text);

    // —— 第7步：段落保护：对非块级元素行包裹 <p> ——
    text = this._wrapParagraphs(text);

    // —— 第8步：行内格式（在所有块级结构之后）——
    text = this._parseInline(text);

    // —— 最后：恢复代码块 ——
    text = text.replace(/\x00CB(\d+)\x00/g, function(m, idx) {
      return codeBlocks[+idx].html;
    });

    return text.trim();
  },

  // ========= 引用块解析（支持嵌套） =========
  _parseBlockquotes: function(text) {
    var lines = text.split('\n');
    var result = [];
    var stack = []; // 结构：{ depth, contentLines }

    for (var i = 0; i < lines.length; i++) {
      var line = lines[i];
      var m = line.match(/^(>{1,})\s?(.*)$/);
      if (m) {
        var depth = m[1].length;
        var content = m[2];

        // 栈顶深度 < 当前深度 → 压栈
        while (stack.length > 0 && stack[stack.length - 1].depth < depth) {
          stack.push({ depth: stack[stack.length - 1].depth + 1, contentLines: [] });
        }
        // 栈顶深度 > 当前深度 → 弹栈
        while (stack.length > 0 && stack[stack.length - 1].depth > depth) {
          var popped = stack.pop();
          var innerHtml = this._buildBlockquote(popped.contentLines, popped.depth);
          if (stack.length > 0) {
            stack[stack.length - 1].contentLines.push(innerHtml);
          } else {
            result.push(innerHtml);
          }
        }

        if (stack.length === 0) {
          stack.push({ depth: depth, contentLines: [] });
        }
        stack[stack.length - 1].contentLines.push(content || '');
      } else {
        // 非引用行 → 全部弹栈
        while (stack.length > 0) {
          var p = stack.pop();
          var h = this._buildBlockquote(p.contentLines, p.depth);
          if (stack.length > 0) {
            stack[stack.length - 1].contentLines.push(h);
          } else {
            result.push(h);
          }
        }
        result.push(line);
      }
    }

    while (stack.length > 0) {
      var p = stack.pop();
      var h = this._buildBlockquote(p.contentLines, p.depth);
      if (stack.length > 0) {
        stack[stack.length - 1].contentLines.push(h);
      } else {
        result.push(h);
      }
    }

    return result.join('\n');
  },

  _buildBlockquote: function(contentLines, depth) {
    var content = contentLines.join('\n');
    // 引用内部的块级元素做递归解析
    content = this._parseTables(content);
    content = this._parseLists(content);
    content = this._wrapParagraphs(content);
    content = this._parseInline(content);
    return '<blockquote>' + content + '</blockquote>';
  },

  // ========= 表格解析（严格判定） =========
  _parseTables: function(text) {
    var lines = text.split('\n');
    var result = [];
    var i = 0;

    while (i < lines.length) {
      var line = lines[i];

      // 真正的表格必须满足：包含至少 2 个 |，且第2行是分隔行（含有 --- ）
      if (this._isTableStart(lines, i)) {
        var tableLines = [];
        // 收集表头行
        tableLines.push(lines[i]);
        tableLines.push(lines[i + 1]);
        i += 2;
        // 收集数据行（以 | 开头或包含 | 且不匹配其他块级结构）
        while (i < lines.length) {
          var tl = lines[i].trim();
          if (tl === '' || tl.match(/^<h[1-6]>/) || tl.match(/^<pre>/) || tl.match(/^<blockquote>/) ||
              tl.match(/^<(ul|ol|table|hr)>/) || tl.match(/^#{1,6}\s/)) {
            break;
          }
          if (tl.indexOf('|') === -1) break;
          // 跳过代码块标记行
          if (tl.indexOf('\x00CB') !== -1) break;
          tableLines.push(lines[i]);
          i++;
        }
        result.push(this._parseTable(tableLines));
      } else {
        result.push(line);
        i++;
      }
    }

    return result.join('\n');
  },

  _isTableStart: function(lines, idx) {
    if (idx + 1 >= lines.length) return false;
    var l1 = lines[idx].trim();
    var l2 = lines[idx + 1].trim();
    // 第1行必须包含 | 且不是已处理块
    if (l1.indexOf('|') === -1) return false;
    if (l1.match(/^</)) return false;
    // 第2行必须是分隔行：至少包含两个 |---| 片段
    if (!l2.match(/\|[\s:]*-{3,}[\s:]*\|/)) return false;
    return true;
  },

  _parseTable: function(lines) {
    if (lines.length < 2) return lines.join('\n');

    // 辅助：按 | 切分行，去掉首尾空元素但保留中间空单元格
    function splitRow(row) {
      var parts = row.split('|');
      // 去掉首尾空元素（Markdown 表格首尾 | 产生的空串）
      if (parts.length > 0 && parts[0].trim() === '') parts.shift();
      if (parts.length > 0 && parts[parts.length - 1].trim() === '') parts.pop();
      return parts;
    }

    var alignments = [];
    var alignCells = splitRow(lines[1]);
    for (var a = 0; a < alignCells.length; a++) {
      var ac = alignCells[a].trim();
      if (ac.charAt(0) === ':' && ac.charAt(ac.length - 1) === ':') alignments.push('center');
      else if (ac.charAt(ac.length - 1) === ':') alignments.push('right');
      else if (ac.charAt(0) === ':') alignments.push('left');
      else alignments.push(null);
    }

    var html = '<table>\n';

    // 表头
    var headerCells = splitRow(lines[0]);
    html += '<thead>\n<tr>';
    for (var h = 0; h < headerCells.length; h++) {
      var al = alignments[h] || null;
      html += '<th' + (al ? ' align="' + al + '"' : '') + '>' + headerCells[h].trim() + '</th>';
    }
    html += '</tr>\n</thead>\n<tbody>\n';

    // 数据行
    for (var r = 2; r < lines.length; r++) {
      var cells = splitRow(lines[r]);
      if (cells.length === 0) continue;
      html += '<tr>';
      for (var c = 0; c < cells.length; c++) {
        var al = alignments[c] || null;
        html += '<td' + (al ? ' align="' + al + '"' : '') + '>' + cells[c].trim() + '</td>';
      }
      html += '</tr>\n';
    }

    html += '</tbody>\n</table>\n';
    return html;
  },

  // ========= 列表解析 =========
  _parseLists: function(text) {
    var lines = text.split('\n');
    var result = [];
    var i = 0;

    while (i < lines.length) {
      var line = lines[i];
      var trimmed = line.trim();

      // 检测是否块级 HTML
      if (trimmed.match(/^<\/?(?:pre|blockquote|table|h[1-6]|hr)/)) {
        result.push(line);
        i++;
        continue;
      }

      var ulMatch = trimmed.match(/^(\*|-)\s+(.*)$/);
      var olMatch = trimmed.match(/^(\d+)\.\s+(.*)$/);

      if (ulMatch || olMatch) {
        var listType = ulMatch ? 'ul' : 'ol';
        var items = [];
        var itemContent = ulMatch ? ulMatch[2] : olMatch[2];
        items.push(itemContent);
        i++;

        // 收集后续连续的列表项
        while (i < lines.length) {
          var nextTrimmed = lines[i].trim();
          if (nextTrimmed.match(/^<\/?(?:pre|blockquote|table|h[1-6]|hr)/)) break;
          if (nextTrimmed.match(/^#{1,6}\s/)) break;

          var nextUl = nextTrimmed.match(/^(\*|-)\s+(.*)$/);
          var nextOl = nextTrimmed.match(/^(\d+)\.\s+(.*)$/);

          // 如果是空行后面有新段落 → 结束列表
          if (nextTrimmed === '') {
            // 再往后看一行
            if (i + 1 < lines.length) {
              var nn = lines[i + 1].trim();
              if (nn !== '' && !nn.match(/^(\*|-|\d+\.)\s/)) break;
            }
            i++;
            continue;
          }

          if (nextUl || nextOl) {
            var nt = nextUl ? 'ul' : 'ol';
            var nc = nextUl ? nextUl[2] : nextOl[2];
            if (nt !== listType) break;
            items.push(nc);
            i++;
          } else {
            break;
          }
        }

        var listHtml = '<' + listType + '>\n';
        for (var j = 0; j < items.length; j++) {
          listHtml += '<li>' + items[j] + '</li>\n';
        }
        listHtml += '</' + listType + '>\n';
        result.push(listHtml);
      } else {
        result.push(line);
        i++;
      }
    }

    return result.join('\n');
  },

  // ========= 段落包裹 =========
  _wrapParagraphs: function(text) {
    var blocks = text.split(/\n{2,}/);
    var result = [];

    for (var b = 0; b < blocks.length; b++) {
      var block = blocks[b].trim();
      if (!block) continue;

      // 块级 HTML 元素不包裹 <p>
      if (block.match(/^<h[1-6]>/i) || block.match(/^<pre>/i) || block.match(/^<table>/i) ||
          block.match(/^<ul>/i) || block.match(/^<ol>/i) || block.match(/^<hr>/i) ||
          block.match(/^<blockquote>/i) || block.match(/^<tr>/i) ||
          block.indexOf('\x00CB') !== -1) {
        result.push(block);
        continue;
      }

      // 纯文本块逐行包裹 <p>（块内换行合并）
      var lines = block.split('\n');
      var paraLines = [];
      for (var l = 0; l < lines.length; l++) {
        var lc = lines[l].trim();
        if (lc) paraLines.push(lc);
      }
      if (paraLines.length > 0) {
        result.push('<p>' + paraLines.join(' ') + '</p>');
      }
    }

    return result.join('\n');
  },

  // ========= 行内格式解析 =========
  _parseInline: function(text) {
    // 保护已生成的 HTML 标签
    // 行内代码（必须在粗体/斜体之前）
    text = text.replace(/`([^`]+)`/g, function(m, code) {
      return '<code>' + code.replace(/</g, '&lt;').replace(/>/g, '&gt;') + '</code>';
    });

    // 粗体 + 斜体 *** ***（必须在 ** 之前处理）
    text = text.replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>');
    // 粗体 ** **
    text = text.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
    // 斜体 * *（用零宽断言避免匹配到 ** 的部分）
    text = text.replace(/(^|[\s,;:.!?([{>\/])\*(?!\*)(.+?)(?<!\*)\*(?=[\s,;:.!?)\]}\/<]|$)/g, '$1<em>$2</em>');

    // 图片
    text = text.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1">');
    // 链接
    text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');

    return text;
  }
};

})();
